import { React, useState, useEffect } from "react";
import './BaPricing.css';

import TextField from '@mui/material/TextField';
import TextareaCopyButton from 'components/text-area-copy-button/text-area-copy-button.js';

// Board shows in order...
// Attacker Points attacker level
// defender
// collector
// healer

const emptyBaPoints = {
  attacker: { points: '', level: '' },
  defender: { points: '', level: '' },
  collector: { points: '', level: '' },
  healer: { points: '', level: '' }
};

function BaPricing() {
  const [baPoints, setBaPoints] = useState({ ...emptyBaPoints} );

    useEffect(() => {
      setBaPoints({ ...emptyBaPoints} );
    }, []);

  function handleValueChanged (event, role, component) {
    const newValue = event.target.value;
    let newBaPoints = { ...baPoints };
    newBaPoints[role][component] = newValue;
    setBaPoints(newBaPoints);
  }

  function clear () {
    setBaPoints({
      attacker: { points: '', level: '' },
      defender: { points: '', level: '' },
      collector: { points: '', level: '' },
      healer: { points: '', level: '' }
    });
  }

  function calculatePrice () {
    let currentPoints = 0;
    for (let key in baPoints) {
      const level = Number(baPoints[key].level);
      const points = Number(baPoints[key].points);
      if (level <= 1) { currentPoints = currentPoints + points };
      if (level === 2) { currentPoints = currentPoints + 200 + points };
      if (level === 3) { currentPoints = currentPoints + 200 + 300 + points };
      if (level === 4) { currentPoints = currentPoints + 200 + 300 + 400 + points };
      if (level >= 5) { currentPoints = currentPoints + 200 + 300 + 400 + 500 };
    }
    // Each role has 1400 points, so 1400 * 4 = 5600 points for level 5 all
    // Price is determined by (pointsRemaining) / 360 * 29.75 = price in millions
    const price = (5600 - currentPoints) / 360 * 29.75;
    return price.toFixed(2) + 'm';
  }

  return (
    <div className="container">
      <div className="grid-container">
          <div className="clear" onClick={clear}>
            { baPoints !== emptyBaPoints
              ? <div>[Clear]</div>
              : null
            }
          </div>
          <label>
            Points
          </label>
          <label>
            Level
          </label>
          <label>
            Attacker
          </label>
          <TextField
            id="outlined-required"
            label="Attacker points"
            value={baPoints.attacker.points}
            onChange={(event) =>
              handleValueChanged(event, 'attacker', 'points')
            }
          />
          <TextField
            id="outlined-required"
            label="Attacker level"
            type="number"
            value={baPoints.attacker.level}
            onChange={(event) =>
              handleValueChanged(event, 'attacker', 'level')
            }
          />
          <label>
            Defender
          </label>
          <TextField
            id="outlined-required"
            label="Defender points"
            type="number"
            value={baPoints.defender.points}
            onChange={(event) =>
              handleValueChanged(event, 'defender', 'points')
            }
          />
          <TextField
            id="outlined-required"
            label="Defender level"
            type="number"
            value={baPoints.defender.level}
            onChange={(event) =>
              handleValueChanged(event, 'defender', 'level')
            }
          />
          <label>
            Collector
          </label>
          <TextField
            id="outlined-required"
            label="Collector points"
            type="number"
            value={baPoints.collector.points}
            onChange={(event) =>
              handleValueChanged(event, 'collector', 'points')
            }
          />
          <TextField
            id="outlined-required"
            label="Collector level"
            type="number"
            value={baPoints.collector.level}
            onChange={(event) =>
              handleValueChanged(event, 'collector', 'level')
            }
          />
          <label>
            Healer
          </label>
          <TextField
            id="outlined-required"
            label="Healer points"
            type="number"
            value={baPoints.healer.points}
            onChange={(event) =>
              handleValueChanged(event, 'healer', 'points')
            }
          />
          <TextField
            id="outlined-required"
            label="Healer level"
            type="number"
            value={baPoints.healer.level}
            onChange={(event) =>
              handleValueChanged(event, 'healer', 'level')
            }
          />
      </div>
      <div className="pricing-block">
        <label className="pricing-label">Price:</label>
        <div className="pricing-field">
          <TextareaCopyButton
            editable={false}
            value={calculatePrice()}
          />
        </div>
      </div>
    </div>
   // </Box>
  );
}

export default BaPricing;